export async function getTeamsList() {
  return ontology.teams.map(t => ({ id: t.id, name: t.name }));
}

function getCurrentTeamId(): string {
  const teamId = useTeamStore.getState().selectedTeam;
  return teamId;
}

export function getStudyVariables() {
  const teamId = getCurrentTeamId();
  const team = ontology.teams.find(t => t.id === teamId);
  assert(team, `Team with id ${teamId} not found`);
  return team.studyVariables;
}

export function getExpertPrompts(studyVariables: StudyVariables) {
  const teamId = getCurrentTeamId();
  const team = ontology.teams.find(t => t.id === teamId);
  assert(team, `Team with id ${teamId} not found`);
  const { brands, indications } = studyVariables;

  assert(brands[0], `studyVariables::brands[0] not found`);
  assert(indications[0], `studyVariables::indications[0] not found`);
  const brandName = brands[0].name;
  const brandAName = brands[0].name;
  const brandBName = brands[1]?.name ?? 'None';
  const indicationName = indications[0].name;
  const diseaseState = indications[0].name.toLowerCase();

  return team.promptCategories.map(processCategory => {
    return {
      ...processCategory,
      categories: processCategory.categories.map(promptCategory => {
        return {
          ...promptCategory,
          templates: promptCategory.templates.map(template => {
            // Replace instances of {{brand}}, {{indication}}, and {{disease_state}} in the prompt template
            const updatedPromptTemplate = template.promptTemplate
              .replace(/{{brand}}/g, brandName)
              .replace(/{{brand_a}}/g, brandAName)
              .replace(/{{brand_b}}/g, brandBName)
              .replace(/{{indication}}/g, indicationName)
              .replace(/{{disease_state}}/g, diseaseState);

            return {
              ...template,
              promptTemplate: updatedPromptTemplate,
            };
          }),
        };
      }),
    };
  });
}

export function findPersonaPath(targetPersonaId: string): string[] {
  function searchAudiences(audience: Audience, currentPath: string[]): string[] | null {
    // Add current audience to path
    const newPath = [...currentPath, audience.name];

    // Check personas at current audience level
    for (const personaSet of audience.personaSets) {
      for (const persona of personaSet.personas) {
        if (persona.id === targetPersonaId) {
          // Found the target persona - return path with persona name
          return [...newPath, persona.name];
        }
      }
    }

    // Recursively search through sub-categories
    for (const category of audience.categories) {
      const result = searchAudiences(category, newPath);
      if (result) {
        return result;
      }
    }

    return null;
  }

  // Search through all audiences in study variables
  for (const team of ontology.teams) {
    for (const audience of team.studyVariables.audiences) {
      const path = searchAudiences(audience, []);
      if (path) {
        return path;
      }
    }
  }

  return [];
}

const CLIENT_ID = process.env.NEXT_PUBLIC_ENTRA_ID_APPLICATION_CLIENT_ID ?? '';
const TENANT_ID = process.env.NEXT_PUBLIC_ENTRA_ID_TENANT_ID ?? '';
const API_SCOPE_NAME = process.env.NEXT_PUBLIC_ENTRA_ID_API_SCOPE_NAME ?? '.default';
const REDIRECT_URL = process.env.NEXT_PUBLIC_ENTRA_ID_REDIRECT_URL ?? '';

export const msalConfig = {
  auth: {
    clientId: CLIENT_ID,
    authority: `https://login.microsoftonline.com/${TENANT_ID}`,
    redirectUri: REDIRECT_URL,
    postLogoutRedirectUri: '/',
    scope: API_SCOPE,
  },
  cache: {
    // Optional
    cacheLocation: 'localStorage', // Configures cache location. "sessionStorage" is more secure, but "localStorage" gives you SSO between tabs.
    storeAuthStateInCookie: false, // Set this to "true" if you are having issues on IE11 or Edge
  },
};

export const loginRequest = {
  scopes: [],
};

export const userDataLoginRequest = {
  scopes: ['user.read'],
};

export const graphConfig = {
  graphMeEndpoint: 'https://graph.microsoft.com/v1.0/me',
};

export const msalInstance = new PublicClientApplication(msalConfig);

export function initializeMsal() {
  // Account selection logic is app dependent. Adjust as needed for different use cases.
  const accounts = msalInstance.getAllAccounts();
  if (accounts.length > 0) {
    msalInstance.setActiveAccount(accounts[0]);
  }

  msalInstance.addEventCallback(async event => {
    if (event.eventType === EventType.LOGIN_SUCCESS && event.payload) {
      const payload = event.payload as AuthenticationResult;
      const account = payload.account;
      msalInstance.setActiveAccount(account);

      // Track user login in Mixpanel
      if (account.idTokenClaims?.oid) {
        const userId = account.idTokenClaims.oid as string;
        const userEmail = account.username;

        mixpanel.identify(userId);
        mixpanel.people.set({
          $email: userEmail,
          $name: userEmail,
          user_id: userId,
        });

        trackUserLogin(userId);
        trackVisitStart(userId);
      }
    }
  });
}

export async function getToken() {
  const authToken = await getCurrentToken(msalInstance);

  return authToken;
}

export const handleLogin = (loginType = 'redirect') => {
  if (loginType === 'popup') {
    msalInstance.loginPopup(loginRequest).catch(e => {
      console.error(`loginPopup failed: ${e}`);
    });
  } else if (loginType === 'redirect') {
    msalInstance.loginRedirect(loginRequest).catch(e => {
      console.error(`loginRedirect failed: ${e}`);
    });
  }
};

type LogoutType = 'redirect' | 'popup' | 'silent';
export const handleLogout = (logoutType: LogoutType = 'redirect') => {
  const account = msalInstance.getActiveAccount();
  if (account?.idTokenClaims?.oid) {
    trackVisitEnded(account.idTokenClaims.oid as string);
  }

  if (logoutType === 'popup') {
    msalInstance.logoutPopup().catch((e: any) => {
      console.error(`logoutPopup failed: ${e}`);
    });
  } else if (logoutType === 'redirect') {
    const logoutRequest = {
      account: account,
      postLogoutRedirectUri: '/',
    };
    msalInstance.logoutRedirect(logoutRequest).catch(e => {
      console.error(`logoutRedirect failed: ${e}`);
    });
  } else if (logoutType === 'silent') {
    msalInstance
      .logoutRedirect({
        onRedirectNavigate: () => false,
        account: account,
      })
      .catch((e: any) => {
        console.error(`logoutPopup failed: ${e}`);
      });
  }
};

export async function getUserPhotoAvatar() {
  const instance = msalInstance;
  const account = instance.getActiveAccount();

  if (!account) {
    throw new Error({
      title: 'No active account! Verify a user has been signed in and setActiveAccount has been called.',
      statusCode: 401,
    });
  }

  const tokenResponse = await instance.acquireTokenSilent({
    ...userDataLoginRequest,
    account: account,
  });

  const headers = new Headers();
  headers.append('Authorization', `Bearer ${tokenResponse.accessToken}`);

  const photoEndpoint = `${graphConfig.graphMeEndpoint}/photo/$value`;

  const options = {
    method: 'GET',
    headers: headers,
  };

  return fetch(photoEndpoint, options)
    .then(response => response.blob())
    .then(blob => {
      const url = URL.createObjectURL(blob);

      return url;
    })
    .catch(error => console.log(error));
}

export async function getCurrentToken(msalInstance: PublicClientApplication): Promise<string | null> {
  const acquireAccessToken = async () => {
    const activeAccount = msalInstance.getActiveAccount(); // This will only return a non-null value if you have logic somewhere else that calls the setActiveAccount API
    const accounts = msalInstance.getAllAccounts();

    if (!activeAccount && accounts.length === 0) {
      /*
       * User is not signed in. Throw error or wait for user to login.
       * Do not attempt to log a user in outside of the context of MsalProvider
       */
      return null;
    }
    const request = {
      scopes: [API_SCOPE],
      account: activeAccount || accounts[0],
    };

    try {
      const authResult = await msalInstance.acquireTokenSilent(request);
      return authResult.accessToken;
    } catch (error) {
      // If silent acquisition fails, try acquiring token through popup or redirect
      try {
        const authResult = await msalInstance.acquireTokenPopup(request);
        return authResult.accessToken;
      } catch (error) {
        console.error('Error acquiring token:', error);
        return null;
      }
    }
  };

  var token = null;

  if (typeof window !== 'undefined') {
    token = await acquireAccessToken();
  }

  return token;
}

export function extractInitials(name: string | null | undefined): string {
  if (!name) return '';

  const ignoreList = ['ext']; // titles to ignore

  return name
    .split(',')
    .filter(part => !ignoreList.includes(part.toLowerCase()))
    .map(part => part.trim())
    .map(part => part[0])
    .join('')
    .toUpperCase();
}

const extractFirstName = (fullName: string): string => {
  const trimmedName = fullName.trim();
  const firstSpace = trimmedName.indexOf(' ');
  return firstSpace > 0 ? trimmedName.slice(0, firstSpace) : trimmedName;
};

export function getUserInfo(): {
  name: string;
  id: string;
} {
  // Check if we're in a browser environment
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return { name: '', id: '' };
  }

  const cookie = document.cookie;
  if (!cookie) return { name: '', id: '' };

  const gatewayUser = cookie.split('; ').find(row => row.startsWith('gateway-user='));
  if (!gatewayUser) return { name: '', id: '' };

  const cookieValue = gatewayUser.split('=')[1];
  const decodedValue = decodeURIComponent(cookieValue);
  const userData = JSON.parse(decodedValue);

  return { 
    name: extractFirstName(userData.name.replace(/\+/g, ' ')), 
    id: userData.id 
  };
}

const createAxiosInstance = (): AxiosInstance => {
  const instance = axios.create({
    baseURL: AI_SERVICE_URL,
    headers: {
      'Content-Type': 'application/json',
    },
    withCredentials: true,
  });

  instance.interceptors.request.use(
    async config => {
      const currentTime = Date.now();
      if (currentTime - lastRequestTime > MAX_INACTIVITY) {
        handleLogout('silent');
        return Promise.reject(new axios.Cancel('Session expired due to inactivity.'));
      }

      lastRequestTime = currentTime;

      config.headers['X-Origin-URL'] = window.location.href;
      return config;
    },
    error => Promise.reject(error),
  );

  instance.interceptors.response.use(
    response => response,
    (error: AxiosError) => {
      if (error.response?.status === 401 || error.response?.status === 403) {
        const redirectUrl = (error.response?.data as { redirectUrl?: string })?.redirectUrl;
        if (redirectUrl) {
          window.location.href = redirectUrl;
        } else {
          console.error('Authentication error:', error.response.status);
        }
      }
      return Promise.reject(error);
    },
  );

  return instance;
};

export type Message = {
  type: 'user' | 'assistant';
  message: string;
  documents?: string[];
};

export type DataStore = {
  messages_0: Message[];
  messages_1: Message[];
  messages_2: Message[];
  loading: boolean;
  streamedResponse: Message;
  setStreamedResponse: (message: Message) => void;
  setLoading: (loading: boolean) => void;
  addUserMessage: (persona: number, message: string) => void;
  addAssistantMessage: (persona: number, message: string) => void;

  addDocumentsToLastMessage: (persona: number, documents: string[]) => void;
  clearPersonaMessages: (persona: number) => void;
  clearAllPersonaMessages: () => void;

  getMessages: (persona: number) => Message[];
};

export const createDataStore: StateCreator<DataStore, [], [], DataStore> = (set, get) => ({
  messages_0: [],
  messages_1: [],
  messages_2: [],
  loading: false,
  streamedResponse: { type: 'assistant', message: '' },
  setStreamedResponse: (message: Message) => {
    set({ streamedResponse: message });
  },
  setLoading: (loading: boolean) => {
    set({ loading });
  },
  addUserMessage: (persona: number, message: string) => {
    const userMessage: Message = {
      type: 'user',
      message,
    };
    switch (persona) {
      case 0:
        set(state => {
          return {
            messages_0: [...state.messages_0, userMessage],
          };
        });
        break;
      case 1:
        set(state => {
          return {
            messages_1: [...state.messages_1, userMessage],
          };
        });
        break;
      case 2:
        set(state => {
          return {
            messages_2: [...state.messages_2, userMessage],
          };
        });
        break;
    }
  },
  addAssistantMessage: (persona: number, message: string) => {
    const assistantMessage: Message = {
      type: 'assistant',
      message,
    };
    switch (persona) {
      case 0:
        set(state => {
          return {
            messages_0: [...state.messages_0, assistantMessage],
          };
        });
        break;
      case 1:
        set(state => {
          return {
            messages_1: [...state.messages_1, assistantMessage],
          };
        });
        break;
      case 2:
        set(state => {
          return {
            messages_2: [...state.messages_2, assistantMessage],
          };
        });
        break;
    }
  },
  clearPersonaMessages: persona => {
    set(state => {
      const key = `messages_${persona}`;
      return {
        [key]: [],
      };
    });
  },

  addDocumentsToLastMessage: (persona, documents) => {
    const key = `messages_${persona}`;
    set(state => {
      // @ts-ignore
      const messages = state[key];
      const lastMessage = messages[messages.length - 1];
      if (lastMessage) {
        lastMessage.documents = documents;

        return {
          [key]: [...messages.slice(0, -1), lastMessage],
        };
      }
      return state;
    });
  },
  getMessages: persona => {
    switch (persona) {
      case 0:
        return get().messages_0;
      case 1:
        return get().messages_1;
      case 2:
        return get().messages_2;
    }
    return [];
  },
  clearAllPersonaMessages: () => {
    set({
      messages_0: [],
      messages_1: [],
      messages_2: [],
    });
  },
});

