interface Team {
  id: string;
  name: string;
}

interface TeamStore {
  selectedTeam: string;
  teams: Team[];
  isLoading: boolean;
  isSwitchingTeam: boolean;
  isInitialized: boolean;
  setSelectedTeam: (teamId: string) => void;
  setTeams: (teams: Team[]) => void;
  setIsLoading: (loading: boolean) => void;
  clearSelection: () => void;
  setIsSwitchingTeam: (switching: boolean) => void;
  setIsInitialized: (initialized: boolean) => void;
}

export const useTeamStore = create<TeamStore>()(
  persist(
    (set, get) => ({
      selectedTeam: '',
      teams: [],
      isLoading: false,
      isSwitchingTeam: false,
      isInitialized: false,
      setSelectedTeam: (teamId: string) => set({ selectedTeam: teamId }),
      setTeams: (teams: Team[]) => set({ teams }),
      setIsLoading: (loading: boolean) => set({ isLoading: loading }),
      clearSelection: () => set({ isSwitchingTeam: true }),
      setIsSwitchingTeam: (switching: boolean) => set({ isSwitchingTeam: switching }),
      setIsInitialized: (initialized: boolean) => set({ isInitialized: initialized }),
    }),
    {
      name: 'team-storage', // localStorage key
      partialize: (state) => ({ selectedTeam: state.selectedTeam, isSwitchingTeam: state.isSwitchingTeam }), // Only persist selectedTeam
      onRehydrateStorage: () => (state) => {
        // This callback is called after the persisted state is rehydrated
