export type FeatureFlag = Flag;

/**
 * Utility class for resolving feature flags based on study overrides and ontology defaults.
 */
export class FeatureFlagResolver {
  private featureFlags: FeatureFlags;

  constructor() {
    // Initialize with feature flags from the ontology
    this.featureFlags = ontology.feature_flags;
  }

  /**
   * Get the feature flag definition from the ontology.
   */
  private getFlagDefinition(flagId: string): FeatureFlag | null {
    if (!(flagId in this.featureFlags)) {
      return null;
    }
    return this.featureFlags[flagId as keyof FeatureFlags];
  }

  /**
   * Resolve the state of a feature flag for a given study.
   * 
   * @param flagId - The ID of the feature flag to resolve
   * @param studyOverrides - Optional FeatureFlagOverrides containing study-level feature flag overrides
   * @returns The resolved state of the feature flag
   * @throws Error if the flag_id is not found in ontology
   */
  resolveFlagState(flagId: string, studyOverrides?: FeatureFlagOverrides): boolean {
    // Get the flag definition from the ontology
    const flagDef = this.getFlagDefinition(flagId);
    if (!flagDef) {
      throw new Error(`Feature flag '${flagId}' not found in ontology`);
    }

    // If no study overrides, return the default state
    if (!studyOverrides?.flags) {
      return flagDef.defaultEnabled;
    }

    // Get the study override for this flag
    if (!(flagId in studyOverrides.flags)) {
      return flagDef.defaultEnabled;
    }

    // Check if study overrides are allowed for this flag
    if (!flagDef.studyOverride.allowed) {
      return flagDef.defaultEnabled;
    }

    // Get the requested state from the study override
    const requestedState = studyOverrides.flags[flagId].enabled;

    // Validate the override based on enable/disable permissions
    if (requestedState && !flagDef.studyOverride.canEnable) {
      return flagDef.defaultEnabled;
    }
    if (!requestedState && !flagDef.studyOverride.canDisable) {
      return flagDef.defaultEnabled;
    }

    return requestedState;
  }

  /**
   * Resolve all feature flags for a study.
   * 
   * @param studyOverrides - Optional FeatureFlagOverrides containing study-level feature flag overrides
   * @returns Map of feature flag IDs to their resolved states
   */
  resolveAllFlags(studyOverrides?: FeatureFlagOverrides): Record<string, boolean> {
    // Resolve each flag
    const resolvedFlags: Record<string, boolean> = {};
    for (const flagId of Object.keys(this.featureFlags)) {
      resolvedFlags[flagId] = this.resolveFlagState(flagId, studyOverrides);
    }

    return resolvedFlags;
  }
}

// Create a singleton instance
export const featureFlagResolver = new FeatureFlagResolver();

export function djb2Hash(s: string): string {
  let hash = 5381;
  for (let i = 0; i < s.length; i++) {
    hash = ((hash << 5) >>> 0) + hash;
    hash = (hash + s.charCodeAt(i)) >>> 0;
  }
  return hash.toString();
}

export function useFeatureFlags(studyOverrides?: FeatureFlagOverrides) {
  // Only recompute flags when studyOverrides changes
  const flags = useMemo(() => {
    // Check if feature flag overrides are enabled via environment variable
    const overridesEnabled = process.env.NEXT_PUBLIC_FEATURE_FLAG_OVERRIDES_ENABLED === 'true';

    // If overrides are disabled, resolve flags without any overrides
    if (!overridesEnabled) {
      return featureFlagResolver.resolveAllFlags();
    }

    return featureFlagResolver.resolveAllFlags(studyOverrides);
  }, [studyOverrides]);

  return flags;
}

export function useFeatureFlag(flagId: string, studyOverrides?: FeatureFlagOverrides): boolean {
  // Only recompute flag when flagId or studyOverrides changes
  const flagEnabled = useMemo(() => {
    // Check if feature flag overrides are enabled via environment variable
    const overridesEnabled = process.env.NEXT_PUBLIC_FEATURE_FLAG_OVERRIDES_ENABLED === 'true';

    try {
      // If overrides are disabled, resolve flag without any overrides
      if (!overridesEnabled) {
        return featureFlagResolver.resolveFlagState(flagId);
      }

      // Resolve flag with overrides if provided
      if (studyOverrides) {
        return featureFlagResolver.resolveFlagState(flagId, studyOverrides);
      }

      // No overrides provided
      return featureFlagResolver.resolveFlagState(flagId);
    } catch (error) {
      // If there's any error (invalid flag ID, etc.), return false
      console.error(`Error resolving feature flag'\${flagId}'`:`, error);
      return false;
    }
  }, [flagId, studyOverrides]);

  return flagEnabled;
}

