const loadFromStorage = (key: string): string[] => {
  try {
    return JSON.parse(localStorage.getItem(key) || '[]');
  } catch {
    return [];
  }
};

export const useResponseReactionsStore = create<ResponseReactionsState>((set, get) => ({
  likedResponses: loadFromStorage('likedResponses'),
  unlikedResponses: loadFromStorage('unlikedResponses'),

  isLiked: (responseId: string) => get().likedResponses.includes(responseId),
  isUnliked: (responseId: string) => get().unlikedResponses.includes(responseId),

  addLike: (responseId: string) => {
    const { likedResponses, unlikedResponses, removeUnlike } = get();
    if (likedResponses.includes(responseId)) return;

    if (unlikedResponses.includes(responseId)) {
      removeUnlike(responseId);
    }

    const newLikedResponses = [...likedResponses, responseId];
    localStorage.setItem('likedResponses', JSON.stringify(newLikedResponses));
    set({ likedResponses: newLikedResponses });
  },

  addUnlike: (responseId: string) => {
    const { unlikedResponses, likedResponses, removeLike } = get();
    if (unlikedResponses.includes(responseId)) return;

    if (likedResponses.includes(responseId)) {
      removeLike(responseId);
    }

    const newUnlikedResponses = [...unlikedResponses, responseId];
    localStorage.setItem('unlikedResponses', JSON.stringify(newUnlikedResponses));
    set({ unlikedResponses: newUnlikedResponses });
  },

  removeLike: (responseId: string) => {
    const { likedResponses } = get();
    const newLikedResponses = likedResponses.filter(id => id !== responseId);
    localStorage.setItem('likedResponses', JSON.stringify(newLikedResponses));
    set({ likedResponses: newLikedResponses });
  },

  removeUnlike: (responseId: string) => {
    const { unlikedResponses } = get();
    const newUnlikedResponses = unlikedResponses.filter(id => id !== responseId);
    localStorage.setItem('unlikedResponses', JSON.stringify(newUnlikedResponses));
    set({ unlikedResponses: newUnlikedResponses });
  },
}));

