export const MarkdownCopy = ({ content, showCopyButton = true, onCopy }: MarkdownCopyProps) => {
  const markdownRef = useRef<HTMLDivElement>(null);

  const copyHtmlToClipboard = async () => {
    if (markdownRef.current) {
      const html = markdownRef.current.innerHTML;
      try {
        // Use the Clipboard API's write method if available (supports rich text)
        if (navigator.clipboard && navigator.clipboard.write) {
          const blobHtml = new Blob([html], { type: 'text/html' });
          // Also provide plain text so that apps not supporting rich text can fall back
          const blobText = new Blob([html], { type: 'text/plain' });
          const clipboardItem = new ClipboardItem({
            'text/html': blobHtml,
            'text/plain': blobText,
          });
          await navigator.clipboard.write([clipboardItem]);
          if (onCopy) onCopy();
        } else if (navigator.clipboard && navigator.clipboard.writeText) {
          // Fallback: copy as plain text
          await navigator.clipboard.writeText(html);
          if (onCopy) onCopy();
        } else {
          // Last-resort fallback: use a temporary textarea and execCommand
          const textArea = document.createElement('textarea');
          textArea.value = html;
          document.body.appendChild(textArea);
          textArea.select();
          document.execCommand('copy');
          document.body.removeChild(textArea);
          if (onCopy) onCopy();
        }
      } catch (error) {
        console.error('Failed to copy HTML:', error);
      }
    }
  };

  return (
    <div className='relative'>
      <div ref={markdownRef}>
        <Markdown className={reportStyles.markdown}>{content}</Markdown>
      </div>

      <div className='flex justify-end mt-2'>
        <div className='w-[30px] h-[30px]'>
          <If condition={showCopyButton}>
            <Tooltip title='Copy to clipboard' placement='top'>
              <IconButton
                size='small'
                onClick={copyHtmlToClipboard}
                sx={{
                  color: 'rgba(0, 0, 0, 0.56)',
                  opacity: 0.4,
                  transition: 'opacity 125ms ease',
                  '&:hover': {
                    opacity: 1,
                  },
                }}
                aria-label='Copy response'
              >
                <ContentCopyIcon fontSize='small' />
              </IconButton>
            </Tooltip>
          </If>
        </div>
      </div>
    </div>
  );
};

