type AutoScrollState = {
  shouldAutoScroll: boolean;
  contentHeight: number;
  isAtBottom: boolean;
  scrollContainer: HTMLDivElement | null;
  contentContainer: HTMLDivElement | null;
  isScrolling: boolean;
  scrollTimeout: NodeJS.Timeout | null;
  lastManualScrollTime: number;

  setShouldAutoScroll: (should: boolean) => void;
  setContentHeight: (height: number) => void;
  setIsAtBottom: (isAtBottom: boolean) => void;
  handleScroll: () => void;

  setScrollContainer: (element: HTMLDivElement | null) => void;
  getScrollContainer: () => HTMLDivElement | null;
  setContentContainer: (element: HTMLDivElement | null) => void;
  getContentContainer: () => HTMLDivElement | null;

  scrollToBottom: () => void;
};

export const useAutoScrollStore = create<AutoScrollState>((set, get) => ({
  shouldAutoScroll: true,
  contentHeight: 0,
  isAtBottom: true,
  scrollContainer: null,
  contentContainer: null,
  isScrolling: false,
  scrollTimeout: null,
  lastManualScrollTime: 0,

  setShouldAutoScroll: should => {
    set({ shouldAutoScroll: should });
  },
  setContentHeight: height => set({ contentHeight: height }),
  setIsAtBottom: isAtBottom => set({ isAtBottom }),

  handleScroll: () => {
    const container = get().getScrollContainer();
    if (!container) return;

    const { scrollTop, scrollHeight, clientHeight } = container;
    const bottom = scrollHeight - scrollTop - clientHeight < 100;

    // Only update lastManualScrollTime if this is a user-initiated scroll (not a programmatic one)
    if (!get().isScrolling) {
      set({ lastManualScrollTime: Date.now() });
    }

    if (bottom) {
      // Only enable auto-scroll if we're at the bottom due to a manual scroll
      // and it's been less than 100ms since the last manual scroll
      const timeSinceLastManualScroll = Date.now() - get().lastManualScrollTime;
      if (!get().isScrolling && timeSinceLastManualScroll < 100) {
        set({ shouldAutoScroll: true });
      }
    } else if (get().shouldAutoScroll) {
      set({ isScrolling: false, scrollTimeout: null, shouldAutoScroll: false });
      clearTimeout(get().scrollTimeout ?? void 0);
    }

    set({ isAtBottom: bottom });
  },

  setScrollContainer: element => {
    get().scrollContainer = element;
  },
  getScrollContainer: () => get().scrollContainer,

  setContentContainer: element => {
    get().contentContainer = element;
  },
  getContentContainer: () => get().contentContainer,

  scrollToBottom: () => {
    const container = get().getScrollContainer();
    if (!container || get().isScrolling) return;

    const currentTimeout = get().scrollTimeout;
    if (currentTimeout) {
      clearTimeout(currentTimeout);
    }

    set({ isScrolling: true });

    requestAnimationFrame(() => {
      container.scrollTo({
        top: container.scrollHeight,
        behavior: 'smooth'
      });
    });

    const timeout = setTimeout(() => {
      set({ isScrolling: false, scrollTimeout: null });
    }, 300);

    set({ scrollTimeout: timeout });
  },
});

