type SessionStore = {
  loadSession: (session: SessionResponse) => void;
  currentSession?: SessionResponse;
  send: (
    message: string,
    events?: {
      onStreamEnd?: ({ newTitle }: { newTitle: string }) => void;
    },
  ) => void;
  setStreamedResponse: (response: { [key: string]: string }) => void;
  isStreaming: boolean;
  streamedResponse: {
    user_query?: string;
    title?: string;
    [key: `get_perspectives_${number}`]: string;
    [key: `get_perspectives_${number}_confidence`]: string;
    citations?: Citation[][];
    summary?: string;
  };

  toggledPersonas: string[];
  setToggledPersonas: (perspectiveIds: string[]) => void;
  togglePersona: (perspectiveId: string) => void;
  isPersonaToggled: (perspectiveId: string) => boolean;
  confidenceScores?: Record<string, number>;
};

export const useSessionStore = create<SessionStore>((set, get) => ({
  loadSession: (session: SessionResponse) => {
    set({ currentSession: session, toggledPersonas: session.payload.info.perspectives.map(p => p.id) });
  },
  currentSession: undefined,
  streamedResponse: {},

  toggledPersonas: [],
  setToggledPersonas: (ids: string[]) => {
    set({ toggledPersonas: ids });
  },
  togglePersona: (id: string) => {
    const { toggledPersonas } = get();
    set({
      toggledPersonas: toggledPersonas.includes(id) ? toggledPersonas.filter(p => p !== id) : [...toggledPersonas, id],
    });
  },
  isPersonaToggled: (id: string) => {
    const { toggledPersonas } = get();
    return toggledPersonas.includes(id);
  },

  send: async (question, events) => {
    const { currentSession, isStreaming } = get();
    if (!currentSession || isStreaming) return;

    const sessionId = currentSession.id;
    const previousMessages = currentSession.payload.messages;
    const previousQuery =
      previousMessages.length > 0 ? (previousMessages[previousMessages.length - 2]?.content as string) : '';

    // Track follow-up query if there was a previous query
    if (previousMessages.length > 0) {
      const { id } = getUserInfo();
      if (id) {
        trackFollowUpQuerySubmitted(id, currentSession.study_id, sessionId, previousQuery, question.trim());
      }
    }

    // Set both streaming state and initial user query simultaneously
    set({
      isStreaming: true,
      streamedResponse: { user_query: question.trim() },
      confidenceScores: undefined,
    });

    const cumulativeResponse = { user_query: question.trim() } as {
      [key: string]: string | Citation[][] | string[];
      [key: `get_perspectives_${number}`]: string;
      [key: `get_perspectives_${number}_confidence`]: string;
    };

    try {
      // Allow the state update to be processed
      await new Promise(resolve => setTimeout(resolve, 0));

      const stream = perspectiveGraphStream({
        question: question.trim(),
        session_id: sessionId,
      });

      let citations: Citation[][] = [];
      for await (const chunk of stream) {
        const singleKey = Object.keys(chunk)[0];
        if (!singleKey) continue;
        if (!chunk[singleKey]) continue;

        const keys = Object.keys(chunk[singleKey]);
        const validKeys = ['summary', 'title', 'get_perspectives_[0-9]+', 'get_perspectives_[0-9]+_confidence'];

        keys.forEach(key => {
          for (const regexPattern of validKeys) {
            const regex = new RegExp(regexPattern);
            if (regex.test(key)) {
              cumulativeResponse[key] = chunk[singleKey][key];
            }
          }
        });

        // save citations as we receive them
        if (keys.includes('citations')) {
          citations = chunk[singleKey]['citations'];
        }

        if (keys.includes('summary')) {
          // Show citations after all perspectives are shown
          cumulativeResponse['citations'] = citations;
        }

        set({ streamedResponse: { ...cumulativeResponse } });

        await new Promise(resolve => setTimeout(resolve, 10));
      }
    } finally {
      // append payload to session
      const copy = JSON.parse(JSON.stringify(currentSession));
      // update title if it is set
      if (cumulativeResponse.title) {
        copy.payload.info.title = cumulativeResponse.title;
      }

      copy.payload.messages.push({
        role: 'user',
        content: question,
      });

      const perspectiveContent = currentSession.payload.info.perspectives.map((perspective, index) => ({
        perspective_id: perspective.id,
        content: (cumulativeResponse?.[`get_perspectives_${index}`] as string) ?? '',
        citations: (cumulativeResponse.citations as Citation[][])?.[index] || [],
      }));

      copy.payload.messages.push({
        role: 'perspective',
        summary: cumulativeResponse.summary ?? '',
        content: perspectiveContent,
      });

      const confidenceScores: Record<string, number> = {};
      for (const [index, perspective] of currentSession.payload.info.perspectives.entries()) {
        const confidenceValue = cumulativeResponse.get_perspectives_confidence?.[index];
        if (!confidenceValue) {
          console.warn(`No confidence score found for perspective ${perspective.name} at index ${index}`);
          continue;
        }
        const confidenceValueParsed = parseFloat(String(confidenceValue));
        if (!isNaN(confidenceValueParsed)) {
          confidenceScores[perspective.id] = confidenceValueParsed;
        } else {
          console.warn(
            `Invalid confidence score for perspective ${perspective.name} at index ${index}: ${confidenceValue}`,
          );
        }
      }

      set({
        confidenceScores: Object.keys(confidenceScores).length > 0 ? confidenceScores : undefined,
        streamedResponse: {},
        isStreaming: false,
        currentSession: copy,
      });

      events?.onStreamEnd?.({ newTitle: cumulativeResponse.title as string });
    }
  },
  setStreamedResponse: () => {},
  isStreaming: false,
}));

