const handleCardClick = (item: Audience | PersonaSet) => {
  if ('categories' in item && item.categories.length > 0) {
    setNavigationStack([...navigationStack, item]);
    setCategories(item.categories);
    setPersonaSets([]);
    setBreadcrumb([...breadcrumb, item.name]);
  } else if ('personaSets' in item && item.personaSets.length > 0) {
    setNavigationStack([...navigationStack, item]);
    setCategories([]);
    setPersonaSets(item.personaSets);
    setBreadcrumb([...breadcrumb, item.name, 'Perspectives']);
  } else {
    setCategories([]);
    setPersonaSets([]);
  }
};

const handleBreadcrumbClick = (index: number) => {
  const isLast = index === breadcrumb.length - 1;
  if (isLast || navigationStack.length === index) return;
  const newStack = navigationStack.slice(0, index);
  const lastItem = newStack[newStack.length - 1];

  setNavigationStack(newStack);
  setBreadcrumb(breadcrumb.slice(0, index + 1));

  if (lastItem) {
    if ('personaSets' in lastItem && lastItem.personaSets && lastItem.personaSets.length > 0) {
      setPersonaSets(lastItem.personaSets);
    } else if ('categories' in lastItem && lastItem.categories && lastItem.categories.length > 0) {
      setCategories(lastItem.categories);
    } else {
      setCategories([]);
    }
  } else {
    setCategories(audiences);
  }
  setPersonaSets([]);
  setSelectedPersonas([]);
  setSelectedPersonaSets([]);
};

const handlePersonaSetToggle = (personaSet: PersonaSet) => {
  const isSelected = selectedPersonaSets.includes(personaSet.id);

  if (isSelected) {
    setSelectedPersonaSets([]);
