const updateTitleMutation = useMutation<SavedResponseResponse, Error, { savedResponseId: string; newTitle: string }>({ 
  mutationFn: Queries.SavedResponse.updateTitle,
  onSuccess: updatedSavedResponse => {
    queryClient.setQueryData<SavedResponseResponse[]>(['savedResponses'], oldResponses => {
      if (!oldResponses) return oldResponses;

      return oldResponses.map(response => {
        if (response.id === updatedSavedResponse.id) {
          return {
            ...response,
            payload: {
              ...response.payload,
              info: {
                ...response.payload.info,
                title: updatedSavedResponse.payload.info.title,
              },
            },
          };
        }
        return response;
      });
    });
  },
});

