const handleFlagToggle = (flagId: keyof FeatureFlags) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const isEnabled = event.target.checked;
    const currentFlags = featureFlagOverrides?.flags || {};
    const flagDef = featureFlagResolver['featureFlags'][flagId];
    const flagGroup = flagDef?.group;

    const newOverrides: FeatureFlagOverrides = {
      flags: { ...currentFlags },
    };

    if (isEnabled && flagGroup) {
      const flagsInGroup = Object.entries(featureFlagResolver['featureFlags']).filter([
        (_, def) => def.group === flagGroup,
      ]);

      flagsInGroup.forEach(([groupFlagId]) => {
        newOverrides.flags[groupFlagId] = { enabled: false };
      });

      newOverrides.flags[flagId] = { enabled: true };
    } else {
      newOverrides.flags[flagId] = { enabled: isEnabled };
    }

    setFeatureFlagOverrides(newOverrides);
};

const getFlagState = (flagId: string, flagDef: Flag): boolean => {
    if (!featureFlagOverrides?.flags) {
      return flagDef.defaultEnabled;
    }
    return featureFlagOverrides.flags[flagId]?.enabled ?? flagDef.defaultEnabled;
};

