const handleIndicationChange = (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
  const id = event.target.value;
  const indication = indications.find(ind => ind.id === id);
  if (!indication) throw new Error('HandleIndicationChange::invalid-indication-id');
  const value = indication;
  const newIndications = [...selectedIndications];
  newIndications[index] = value;

  // Ensure no duplicates
  const otherIndex = index === 0 ? 1 : 0;
  if (newIndications[otherIndex] && newIndications[otherIndex].id === value.id) {
    // Clear the other selection if duplicate
    newIndications[otherIndex] = undefined as any;
  }

  // Remove undefined values
  const filteredIndications = newIndications.filter(ind => ind);

  setSelectedIndications(filteredIndications);
};

