const isStepCompleted = (currentStep: number, stepIndex: number) => stepIndex < currentStep;
const isStepCurrent = (currentStep: number, stepIndex: number) => stepIndex === currentStep;
const isStepUpcoming = (currentStep: number, stepIndex: number) => stepIndex > currentStep;

const shouldShowName = (currentStep: number, stepIndex: number, name: string, hasFeatureFlags: boolean) => {
  const nameStepIndex = hasFeatureFlags ? 1 : 0;
  return isStepCompleted(currentStep, stepIndex) && stepIndex === nameStepIndex && !!name;
};

const shouldShowDescription = (
  currentStep: number,
  stepIndex: number,
  description: string,
  hasFeatureFlags: boolean,
) => {
  const descriptionStepIndex = hasFeatureFlags ? 2 : 1;
  return isStepCompleted(currentStep, stepIndex) && stepIndex === descriptionStepIndex && !!description;
};

const shouldShowBrand = (currentStep: number, stepIndex: number, brand: any, hasFeatureFlags: boolean) => {
  const brandStepIndex = hasFeatureFlags ? 3 : 2;
  return isStepCompleted(currentStep, stepIndex) && stepIndex === brandStepIndex && !!brand;
};

const shouldShowIndications = (
  currentStep: number,
  stepIndex: number,
  indications: any[],
  hasFeatureFlags: boolean,
) => {
  const indicationsStepIndex = hasFeatureFlags ? 3 : 2;
  return isStepCompleted(currentStep, stepIndex) && stepIndex === indicationsStepIndex && indications.length > 0;
};

const shouldShowPersonas = (currentStep: number, stepIndex: number, personas: any[], hasFeatureFlags: boolean) => {
  const personasStepIndex = hasFeatureFlags ? 4 : 3;
  return isStepCompleted(currentStep, stepIndex) && stepIndex === personasStepIndex && personas.length > 0;
};

